  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "هل الكاميرا المراقبة العادية تصلح لقراءة اللوحات؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "ليست بالضرورة، حتى إن كانت 8 ميغابكسل. قراءة اللوحات تعتمد على خوارزمية متخصصة ومعالجة صورة مختلفة، لا على دقة المستشعر وحدها."
      }
    },
    {
      "@type": "Question",
      "name": "ما مسافة القراءة الفعّالة لكاميرا قراءة اللوحات؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "تتراوح غالبًا بين 3 و10 أمتار وفق مواصفات المصنّعين، وتتحدد بدقة بناءً على ارتفاع التركيب وزاوية العدسة وعرض الممر."
      }
    },
    {
      "@type": "Question",
      "name": "هل تعمل الكاميرا ليلًا؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "نعم، شريطة أن تحتوي على IR متخصص لأنظمة LPR. الإضاءة الليلية العامة في كاميرات المراقبة لا تكفي لضمان ثبات معدل التعرف بعد غروب الشمس."
      }
    },
    {
      "@type": "Question",
      "name": "ما الذي يرفع فاتورة نظام قراءة لوحات السيارات؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "عدد الممرات، مسافة القراءة المطلوبة، نوع ترخيص البرمجيات، متطلبات الإضاءة الليلية، وحال البنية التحتية القائمة."
      }
    },
    {
      "@type": "Question",
      "name": "كيف يتكامل النظام مع البوابة الأوتوماتيكية الموجودة؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "عبر بروتوكول اتصال بين الكاميرا ووحدة تحكم البوابة. البروتوكول القياسي يختصر التكلفة، والاختلاف بينهما يستلزم وحدة تحويل إضافية."
      }
    },
    {
      "@type": "Question",
      "name": "كم كاميرا يحتاج مدخل ومخرج مجمع سكني أو تجاري؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "كاميرا مستقلة لكل ممر دخول وممر خروج على الأقل. الممرات المزدوجة أو العريضة قد تحتاج كاميرتين لتغطية زوايا مختلفة."
      }
    }
  ]
}
